candidates.raw:
/* 1. Validate configuration */
if (rs_input.enable != 0 && rs_input.enable != 1) {
    rs_output.source = RS_FAULT;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    return;
}
if (!isfinite(rs_config.max_residual_rad) || rs_config.max_residual_rad < 0.0) {
    rs_output.source = RS_FAULT;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    return;
}
if (!isfinite(rs_config.fuse_angle_rad) || rs_config.fuse_angle_rad > ADCS_PI) {
    rs_output.source = RS_FAULT;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    return;
}
if (!isfinite(rs_config.switch_margin_rad) || rs_config.switch_margin_rad < 0.0) {
    rs_output.source = RS_FAULT;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    return;
}
if (!isfinite(rs_config.residual_weight_floor_rad) || rs_config.residual_weight_floor_rad <= 0.0) {
    rs_output.source = RS_FAULT;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    return;
}
if (!isfinite(rs_config.output_alpha) || rs_config.output_alpha <= 0.0 || rs_config.output_alpha > 1.0) {
    rs_output.source = RS_FAULT;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    return;
}
if (rs_config.switch_confirm_cycles < 1 || rs_config.switch_confirm_cycles > 20) {
    rs_output.source = RS_FAULT;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    return;
}
if (rs_config.max_outage_cycles < 1 || rs_config.max_outage_cycles > 20) {
    rs_output.source = RS_FAULT;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    return;
}

/* 2. Determine usability */
adcs_quat_t star_norm, triad_norm;
int star_usable = 0;
int triad_usable = 0;

if (rs_input.star_q_bi != NULL) {
    if (adcs_quat_normalize(rs_input.star_q_bi, &star_norm) == ADCS_OK &&
        isfinite(rs_input.star_residual_rad) && rs_input.star_residual_rad >= 0.0 &&
        rs_input.star_residual_rad <= rs_config.max_residual_rad) {
        star_usable = 1;
    }
}

if (rs_input.triad_q_bi != NULL) {
    if (adcs_quat_normalize(rs_input.triad_q_bi, &triad_norm) == ADCS_OK &&
        isfinite(rs_input.triad_residual_rad) && rs_input.triad_residual_rad >= 0.0 &&
        rs_input.triad_residual_rad <= rs_config.max_residual_rad) {
        triad_usable = 1;
    }
}

/* 3. Primary/Candidate Selection Logic */
rs_source_t p_src = RS_NONE;
rs_source_t c_src = RS_NONE;
adcs_quat_t p_q = {0};
adcs_quat_t c_q = {0};
double p_res = 0.0;
double c_res = 0.0;

// Handle Outage
if (!star_usable && !triad_usable) {
    rs_output.source = RS_NONE;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;

    rs_state.outage++;
    if (rs_state.outage >= rs_config.max_outage_cycles) {
        rs_output.source = RS_FAULT;
    }

    // Blend with previous
    adcs_quat_t prev_q = rs_state.previous_q_bi;
    adcs_quat_t selected = {1.0, 0.0, 0.0, 0.0};
    double dot_sp = prev_q.w * selected.w + prev_q.x * selected.x + prev_q.y * selected.y + prev_q.z * selected.z;
    if (dot_sp < 0.0) {
        selected.w = -selected.w;
        selected.x = -selected.x;
        selected.y = -selected.y;
        selected.z = -selected.z;
    }
    adcs_quat_t blended_raw = {
        (1.0 - rs_config.output_alpha) * prev_q.w + rs_config.output_alpha * selected.w,
        (1.0 - rs_config.output_alpha) * prev_q.x + rs_config.output_alpha * selected.x,
        (1.0 - rs_config.output_alpha) * prev_q.y + rs_config.output_alpha * selected.y,
        (1.0 - rs_config.output_alpha) * prev_q.z + rs_config.output_alpha * selected.z
    };
    adcs_quat_normalize(&blended_raw, &rs_output.q_bi);
    rs_state.previous_q_bi = rs_output.q_bi;
    return;
}
rs_state.outage = 0;

// Initial Assignment
rs_source_t current_primary = rs_state.primary;

if (current_primary == RS_STAR) {
    p_src = RS_STAR;
    c_src = RS_TRIAD;
    p_q = star_norm;
    c_q = triad_norm;
    p_res = rs_input.star_residual_rad;
    c_res = rs_input.triad_residual_rad;
} else if (current_primary == RS_TRIAD) {
    p_src = RS_TRIAD;
    c_src = RS_STAR;
    p_q = triad_norm;
    c_q = star_norm;
    p_res = rs_input.triad_residual_rad;
    c_res = rs_input.star_residual_rad;
} else {
    if (star_usable) {
        p_src = RS_STAR;
        c_src = RS_TRIAD;
        p_q = star_norm;
        c_q = triad_norm;
        p_res = rs_input.star_residual_rad;
        c_res = rs_input.triad_residual_rad;
    } else if (triad_usable) {
        p_src = RS_TRIAD;
        c_src = RS_STAR;
        p_q = triad_norm;
        c_q = star_norm;
        p_res = rs_input.triad_residual_rad;
        c_res = rs_input.star_residual_rad;
    }
}

// Check Loss of Primary
int primary_lost = 0;
if ((p_src == RS_STAR && !star_usable) || (p_src == RS_TRIAD && !triad_usable)) {
    primary_lost = 1;
}

if (primary_lost) {
    if (c_src == RS_STAR && star_usable) {
        p_src = RS_STAR;
        c_src = RS_TRIAD;
        p_q = star_norm;
        c_q = triad_norm;
        p_res = rs_input.star_residual_rad;
        c_res = rs_input.triad_residual_rad;
    } else if (c_src == RS_TRIAD && triad_usable) {
        p_src = RS_TRIAD;
        c_src = RS_STAR;
        p_q = triad_norm;
        c_q = star_norm;
        p_res = rs_input.triad_residual_rad;
        c_res = rs_input.star_residual_rad;
    }
    rs_state.candidate_good = 0;
} else if (star_usable && triad_usable) {
    // Both usable, check margin
    if (p_res - c_res >= rs_config.switch_margin_rad) {
        rs_state.candidate_good++;
        if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
            rs_source_t tmp_s = p_src;
            p_src = c_src;
            c_src = tmp_s;

            adcs_quat_t tmp_q = p_q;
            p_q = c_q;
            c_q = tmp_q;

            double tmp_r = p_res;
            p_res = c_res;
            c_res = tmp_r;

            rs_state.candidate_good = 0;
        }
    } else {
        rs_state.candidate_good = 0;
    }
} else {
    // Single source available
    if (star_usable && !triad_usable) {
        if (p_src != RS_STAR) {
            p_src = RS_STAR;
            c_src = RS_TRIAD;
            p_q = star_norm;
            c_q = triad_norm;
            p_res = rs_input.star_residual_rad;
            c_res = rs_input.triad_residual_rad;
        }
    } else if (triad_usable && !star_usable) {
        if (p_src != RS_TRIAD) {
            p_src = RS_TRIAD;
            c_src = RS_STAR;
            p_q = triad_norm;
            c_q = star_norm;
            p_res = rs_input.triad_residual_rad;
            c_res = rs_input.star_residual_rad;
        }
    }
    rs_state.candidate_good = 0;
}

rs_state.primary = p_src;
rs_state.candidate = c_src;

/* 4. Fusion and Publication Logic */
adcs_quat_t selected_q = {0};
rs_source_t final_source = RS_NONE;

if (p_src == RS_NONE) {
    final_source = RS_NONE;
    selected_q = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
} else if (star_usable && triad_usable) {
    double abs_dot = adcs_quat_abs_dot(&p_q, &c_q);
    double disc_angle = fabs(acos(adcs_clamp(abs_dot, -1.0, 1.0)));

    if (disc_angle <= rs_config.fuse_angle_rad) {
        final_source = RS_FUSED;

        adcs_quat_t star_final = star_norm;
        adcs_quat_t triad_final = triad_norm;

        double dot_st_tr = star_final.w * triad_final.w + star_final.x * triad_final.x + 
                           star_final.y * triad_final.y + star_final.z * triad_final.z;
        if (dot_st_tr < 0.0) {
            triad_final.w = -triad_final.w;
            triad_final.x = -triad_final.x;
            triad_final.y = -triad_final.y;
            triad_final.z = -triad_final.z;
        }

        double w_star = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.star_residual_rad);
        double w_triad = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.triad_residual_rad);

        adcs_quat_t fused_raw = {
            w_star * star_final.w + w_triad * triad_final.w,
            w_star * star_final.x + w_triad * triad_final.x,
            w_star * star_final.y + w_triad * triad_final.y,
            w_star * star_final.z + w_triad * triad_final.z
        };
        adcs_quat_normalize(&fused_raw, &selected_q);

        rs_output.disagreement_rad = disc_angle;
        rs_output.star_weight = w_star;
        rs_output.triad_weight = w_triad;
    } else {
        final_source = p_src;
        selected_q = p_q;
        rs_output.disagreement_rad = disc_angle;
        rs_output.star_weight = 0.0;
        rs_output.triad_weight = 0.0;
    }
} else {
    final_source = p_src;
    selected_q = p_q;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
}

rs_output.source = final_source;

/* 5. Blend with previous */
adcs_quat_t prev_q = rs_state.previous_q_bi;
double dot_sel_prev = selected_q.w * prev_q.w + selected_q.x * prev_q.x + 
                      selected_q.y * prev_q.y + selected_q.z * prev_q.z;
adcs_quat_t aligned_selected = selected_q;
if (dot_sel_prev < 0.0) {
    aligned_selected.w = -selected_q.w;
    aligned_selected.x = -selected_q.x;
    aligned_selected.y = -selected_q.y;
    aligned_selected.z = -selected_q.z;
}

adcs_quat_t blended_raw = {
    (1.0 - rs_config.output_alpha) * prev_q.w + rs_config.output_alpha * aligned_selected.w,
    (1.0 - rs_config.output_alpha) * prev_q.x + rs_config.output_alpha * aligned_selected.x,
    (1.0 - rs_config.output_alpha) * prev_q.y + rs_config.output_alpha * aligned_selected.y,
    (1.0 - rs_config.output_alpha) * prev_q.z + rs_config.output_alpha * aligned_selected.z
};

adcs_quat_normalize(&blended_raw, &rs_output.q_bi);
rs_state.previous_q_bi = rs_output.q_bi;

