if (rs_input.star_q_bi != NULL) {
    if (adcs_quat_normalize(rs_input.star_q_bi, &star_norm) == ADCS_OK &&
        isfinite(rs_input.star_residual_rad) && rs_input.star_residual_rad >= 0.0 &&
        rs_input.star_residual_rad <= rs_config.max_residual_rad) {
