    // Blend with previous
    adcs_quat_t prev_q = rs_state.previous_q_bi;
    adcs_quat_t selected = {1.0, 0.0, 0.0, 0.0};
    double dot_sp = prev_q.w * selected.w + prev_q.x * selected.x + prev_q.y * selected.y + prev_q.z * selected.z;
    if (dot_sp < 0.0) {
        selected.w = -selected.w;
        selected.x = -selected.x;
        selected.y = -selected.y;
        selected.z = -selected.z;
    }
    adcs_quat_t blended_raw = {
        (1.0 - rs_config.output_alpha) * prev_q.w + rs_config.output_alpha * selected.w,
        (1.0 - rs_config.output_alpha) * prev_q.x + rs_config.output_alpha * selected.x,
        (1.0 - rs_config.output_alpha) * prev_q.y + rs_config.output_alpha * selected.y,
        (1.0 - rs_config.output_alpha) * prev_q.z + rs_config.output_alpha * selected.z
    };
    adcs_quat_normalize(&blended_raw, &rs_output.q_bi);
