rs_state.outage = 0;

// Initial Assignment
rs_source_t current_primary = rs_state.primary;

if (current_primary == RS_STAR) {
    p_src = RS_STAR;
    c_src = RS_TRIAD;
    p_q = star_norm;
    c_q = triad_norm;
    p_res = rs_input.star_residual_rad;
    c_res = rs_input.triad_residual_rad;
} else if (current_primary == RS_TRIAD) {
    p_src = RS_TRIAD;
    c_src = RS_STAR;
    p_q = triad_norm;
    c_q = star_norm;
    p_res = rs_input.triad_residual_rad;
    c_res = rs_input.star_residual_rad;
