                           star_final.y * triad_final.y + star_final.z * triad_final.z;
        if (dot_st_tr < 0.0) {
            triad_final.w = -triad_final.w;
            triad_final.x = -triad_final.x;
            triad_final.y = -triad_final.y;
            triad_final.z = -triad_final.z;
        }

        double w_star = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.star_residual_rad);
        double w_triad = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.triad_residual_rad);

        adcs_quat_t fused_raw = {
            w_star * star_final.w + w_triad * triad_final.w,
            w_star * star_final.x + w_triad * triad_final.x,
            w_star * star_final.y + w_triad * triad_final.y,
            w_star * star_final.z + w_triad * triad_final.z
        };
