/* 1. Configuration Validation */
int config_valid = 1;
if (rs_input.enable != 0 && rs_input.enable != 1) config_valid = 0;
if (!isfinite(rs_config.max_residual_rad) || rs_config.max_residual_rad < 0.0) config_valid = 0;
if (!isfinite(rs_config.fuse_angle_rad) || rs_config.fuse_angle_rad < 0.0 || rs_config.fuse_angle_rad > ADCS_PI) config_valid = 0;
