    if (adcs_quat_normalize(rs_input.star_q_bi, &star_norm) == ADCS_OK) {
        if (isfinite(rs_input.star_residual_rad) && rs_input.star_residual_rad >= 0.0 && 
            rs_input.star_residual_rad <= rs_config.max_residual_rad) {
            star_usable = 1;
        }
    }
}

if (rs_input.triad_q_bi != NULL) {
    if (adcs_quat_normalize(rs_input.triad_q_bi, &triad_norm) == ADCS_OK) {
        if (isfinite(rs_input.triad_residual_rad) && rs_input.triad_residual_rad >= 0.0 && 
            rs_input.triad_residual_rad <= rs_config.max_residual_rad) {
            triad_usable = 1;
        }
    }
}

/* 3. Primary/Candidate Selection Logic */
rs_source_t new_primary = RS_NONE;
rs_source_t current_primary = rs_state.primary;

int primary_lost = (current_primary == RS_STAR && !star_usable) || 
                   (current_primary == RS_TRIAD && !triad_usable);

if (current_primary == RS_NONE) {
    if (star_usable) {
        new_primary = RS_STAR;
    } else if (triad_usable) {
        new_primary = RS_TRIAD;
    }
} else if (primary_lost) {
    if (current_primary == RS_STAR && triad_usable) {
        new_primary = RS_TRIAD;
    } else if (current_primary == RS_TRIAD && star_usable) {
        new_primary = RS_STAR;
    } else {
        new_primary = RS_NONE;
    }
} else {
    new_primary = current_primary;
    if (star_usable && triad_usable) {
        double dot = adcs_quat_abs_dot(&star_norm, &triad_norm);
        if (dot > 1.0) dot = 1.0;
        if (dot < -1.0) dot = -1.0;
        double disagreement = acos(dot);

        if (disagreement > rs_config.fuse_angle_rad) {
            rs_source_t alt_source = (new_primary == RS_STAR) ? RS_TRIAD : RS_STAR;
            double res_curr = (new_primary == RS_STAR) ? rs_input.star_residual_rad : rs_input.triad_residual_rad;
            double res_alt = (alt_source == RS_STAR) ? rs_input.star_residual_rad : rs_input.triad_residual_rad;

            if (res_alt < res_curr - rs_config.switch_margin_rad) {
                rs_state.candidate_good++;
                if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
                    new_primary = alt_source;
                    rs_state.candidate_good = 0;
                }
            } else {
                rs_state.candidate_good = 0;
            }
        }
    }
}

rs_state.primary = new_primary;

if (new_primary == RS_NONE) {
    rs_output.source = RS_NONE;
    rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    rs_state.outage++;
    if (rs_state.outage >= rs_config.max_outage_cycles) {
        rs_state.primary = RS_FAULT;
    }
    return;
}

/* 4. Fusion vs Primary Output */
adcs_quat_t selected_q;
rs_source_t final_source = new_primary;

if (star_usable && triad_usable) {
    double dot = adcs_quat_abs_dot(&star_norm, &triad_norm);
    if (dot > 1.0) dot = 1.0;
    if (dot < -1.0) dot = -1.0;
    double disagreement = acos(dot);

    if (disagreement <= rs_config.fuse_angle_rad) {
        final_source = RS_FUSED;

        double s_dot = star_norm.w * triad_norm.w + star_norm.x * triad_norm.x + 
                       star_norm.y * triad_norm.y + star_norm.z * triad_norm.z;
        adcs_quat_t triad_aligned = triad_norm;
        if (s_dot < 0.0) {
            triad_aligned = adcs_quat_conjugate(&triad_norm);
        }

        double w_s = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.star_residual_rad);
        double w_t = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.triad_residual_rad);

        adcs_quat_t sum_q = {
            w_s * star_norm.w + w_t * triad_aligned.w,
            w_s * star_norm.x + w_t * triad_aligned.x,
            w_s * star_norm.y + w_t * triad_aligned.y,
            w_s * star_norm.z + w_t * triad_aligned.z
        };

        adcs_status_t st = adcs_quat_normalize(&sum_q, &selected_q);
        if (st != ADCS_OK) {
            final_source = new_primary;
        }
    }
}

if (final_source != RS_FUSED) {
    if (new_primary == RS_STAR) {
        selected_q = star_norm;
    } else {
        selected_q = triad_norm;
    }
}

/* 5. Blending and Normalization */
