// 1. Configuration Validation
if (rs_input.enable != 0 && rs_input.enable != 1) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_FAULT;
    rs_output.candidate = RS_FAULT;
    rs_output.outage = 0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}
if (rs_config.residual_weight_floor_rad <= 0.0) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_FAULT;
    rs_output.candidate = RS_FAULT;
    rs_output.outage = 0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}
if (rs_config.output_alpha <= 0.0 || rs_config.output_alpha > 1.0) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_FAULT;
    rs_output.candidate = RS_FAULT;
    rs_output.outage = 0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}
if (rs_config.switch_confirm_cycles < 1 || rs_config.switch_confirm_cycles > 20) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_FAULT;
    rs_output.candidate = RS_FAULT;
    rs_output.outage = 0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}
if (rs_config.max_outage_cycles < 1 || rs_config.max_outage_cycles > 20) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_FAULT;
    rs_output.candidate = RS_FAULT;
    rs_output.outage = 0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}
if (rs_config.fuse_angle_rad > ADCS_PI) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_FAULT;
    rs_output.candidate = RS_FAULT;
    rs_output.outage = 0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

// Fault Latch Check
if (rs_output.source == RS_FAULT) {
    return;
}

// 2. Usability Checks
adcs_quat_t star_normed, triad_normed;
int star_usable = 0;
int triad_usable = 0;

if (rs_input.star_q_bi != NULL) {
    if (adcs_quat_normalize(rs_input.star_q_bi, &star_normed) == ADCS_OK) {
        if (isfinite(rs_input.star_residual_rad) && rs_input.star_residual_rad >= 0.0 &&
            rs_input.star_residual_rad <= rs_config.max_residual_rad) {
            star_usable = 1;
        }
    }
}

if (rs_input.triad_q_bi != NULL) {
    if (adcs_quat_normalize(rs_input.triad_q_bi, &triad_normed) == ADCS_OK) {
        if (isfinite(rs_input.triad_residual_rad) && rs_input.triad_residual_rad >= 0.0 &&
            rs_input.triad_residual_rad <= rs_config.max_residual_rad) {
            triad_usable = 1;
        }
    }
}

// 3. Primary Management
int switch_to_star = 0;
int switch_to_triad = 0;

if (rs_state.primary == RS_STAR) {
    if (!star_usable) {
        if (triad_usable) {
            switch_to_triad = 1;
        } else {
            rs_state.primary = RS_NONE;
        }
    } else if (triad_usable) {
        if ((rs_input.star_residual_rad - rs_input.triad_residual_rad) >= rs_config.switch_margin_rad) {
            rs_state.candidate_good++;
            if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
                switch_to_triad = 1;
                rs_state.candidate_good = 0;
            }
        } else {
            rs_state.candidate_good = 0;
        }
    } else {
        rs_state.candidate_good = 0;
    }
} else if (rs_state.primary == RS_TRIAD) {
    if (!triad_usable) {
        if (star_usable) {
            switch_to_star = 1;
        } else {
            rs_state.primary = RS_NONE;
        }
    } else if (star_usable) {
        if ((rs_input.triad_residual_rad - rs_input.star_residual_rad) >= rs_config.switch_margin_rad) {
            rs_state.candidate_good++;
            if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
                switch_to_star = 1;
                rs_state.candidate_good = 0;
            }
        } else {
            rs_state.candidate_good = 0;
        }
    } else {
        rs_state.candidate_good = 0;
    }
