    if (star_usable) {
        rs_state.primary = RS_STAR;
    } else if (triad_usable) {
        rs_state.primary = RS_TRIAD;
    } else {
        rs_state.primary = RS_NONE;
    }
    rs_state.candidate_good = 0;
}

if (switch_to_star) {
    rs_state.primary = RS_STAR;
    rs_state.candidate_good = 0;
} else if (switch_to_triad) {
    rs_state.primary = RS_TRIAD;
    rs_state.candidate_good = 0;
}

// 4. Fusion vs Selection Logic
adcs_quat_t selected_q_bi = {1, 0, 0, 0};
rs_source_t final_source = RS_NONE;

if (star_usable && triad_usable) {
    double abs_dot = adcs_quat_abs_dot(&star_normed, &triad_normed);
    if (abs_dot > 1.0) abs_dot = 1.0;
    double disagreement = 2.0 * acos(abs_dot);

    rs_output.disagreement_rad = disagreement;

    if (disagreement <= rs_config.fuse_angle_rad) {
        double sd = star_normed.w * triad_normed.w + 
                    star_normed.x * triad_normed.x + 
                    star_normed.y * triad_normed.y + 
                    star_normed.z * triad_normed.z;
        adcs_quat_t aligned_triad = (sd < 0.0) ? adcs_quat_conjugate(&triad_normed) : triad_normed;

        double star_w = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.star_residual_rad);
        double triad_w = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.triad_residual_rad);

        rs_output.star_weight = star_w;
        rs_output.triad_weight = triad_w;

        adcs_quat_t weighted_sum;
        weighted_sum.w = star_w * star_normed.w + triad_w * aligned_triad.w;
        weighted_sum.x = star_w * star_normed.x + triad_w * aligned_triad.x;
        weighted_sum.y = star_w * star_normed.y + triad_w * aligned_triad.y;
        weighted_sum.z = star_w * star_normed.z + triad_w * aligned_triad.z;

        if (adcs_quat_normalize(&weighted_sum, &selected_q_bi) != ADCS_OK) {
            selected_q_bi = star_normed;
        }

        final_source = RS_FUSED;
    } else {
        if (rs_state.primary == RS_STAR) {
            selected_q_bi = star_normed;
        } else {
            selected_q_bi = triad_normed;
        }
